エンドポイント追加の解答例を表示
from nicegui import ui, app
import json

def read_data():
    with open("questions.json", "r", encoding="utf-8") as f:
        return json.load(f)

@app.get("/api/questions")
def get_questions():
    return read_data()

@app.get("/api/results")
def get_results():
    return read_data()["results"]

@app.get("/api/questions/{question_id}")
def get_question(question_id: int):
    for question in read_data()["questions"]:
        if question["id"] == question_id:
            return question
    return {"error": "Not found"}

ui.label("診断アプリAPI")
ui.run()

dict の初期化


{} に キー: 値 のペアをカンマ区切りで書いて初期化
変数名は name2score のような「x2y」形式が慣例

2 は「→（to）」の意味

「A2B」は「A to B」で「AからBへ変換」



# {"キー1": 値1, "キー2": 値2, ...} のように初期化
name2score = {"Yamada": 95, "Suzuki": 75}

# print で表示可能
print(name2score)        # {'Yamada': 95, 'Suzuki': 75}
print(type(name2score))  # &lt;class 'dict'&gt;

# 空の dict の初期化
dict_test1 = {}
dict_test2 = dict()

キーの存在確認（in 演算子）

in 演算子でキーや値の存在を確認できる。存在しないキーを指定する前に使うと KeyError を防げる。
name2score = {"Yamada": 95, "Suzuki": 75}

# キーが存在するか確認
if "Yamada" in name2score:
    print(name2score["Yamada"])  # 95

# 存在しないキーも安全にアクセスできる
if "Tanaka" in name2score:
    print(name2score["Tanaka"])
else:
    print("Tanaka は登録されていません")

# not in で「存在しない」を確認
if "Sato" not in name2score:
    print("Sato は未登録")

in 演算子で存在確認

in 演算子でキーが存在するか確認できる。
name2score = {"Yamada": 95, "Suzuki": 75}

if "Yamada" in name2score:
    print("Yamada さんは登録済み")

if "Tanaka" not in name2score:
    print("Tanaka さんは未登録")






in はキーを見る（値ではない）


if 95 in name2score:            # False
if 95 in name2score.values():   # True ← 値を見たいときはこう

辞書内包表記

リスト内包表記の dict 版。{キー: 値 for ... in ...} の形。
# 数 → その2乗 の dict を作る
squares = {x: x ** 2 for x in range(5)}
print(squares)  # {0: 0, 1: 1, 2: 4, 3: 9, 4: 16}
条件付きも書ける。
# 80点以上だけ取り出す
name2score = {"Yamada": 95, "Suzuki": 75, "Takahashi": 80}
passed = {k: v for k, v in name2score.items() if v &gt;= 80}
print(passed)  # {'Yamada': 95, 'Takahashi': 80}
キーと値を入れ替えるのも一行で書ける。
score2name = {v: k for k, v in name2score.items()}
print(score2name)  # {95: 'Yamada', 75: 'Suzuki', 80: 'Takahashi'}

型


ndarray全体は numpy.ndarray
各要素は代入時のリテラルによって決まる

intなら numpy.int64
floatなら numpy.float64

異なる型は混ぜられない（intとfloatを混ぜると 全部floatに統一 される）

import numpy as np

arr = np.array([1, 2, 3, 4])
print(type(arr))    # &lt;class 'numpy.ndarray'&gt;
print(type(arr[0])) # &lt;class 'numpy.int64'&gt;

arr2 = np.array([1.0, 2.0, 3.0, 4.0])
print(type(arr2))    # &lt;class 'numpy.ndarray'&gt;
print(type(arr2[0])) # &lt;class 'numpy.float64'&gt;
